//! RayX's theme: the design system's tokens as an NSH theme document, read through typed keys.
//!
//! The document is `crates/rayx_components/theme.json` ([`DOCUMENT`]), generated by the
//! `rayx-components` skill's `theme_codegen.py` from the Figma DTCG export (never edited by hand).
//! [`crate::register`] registers it, so classes, `token()`, theme files and nsh-base's parts read
//! RayX's tokens.
//!
//! - **Reading.** [`keys`] has one `TokenKey` per token at its path, the variable's WEB code syntax:
//!   `theme/colors/roles/primary/bgHover` is `keys::theme::colors::roles::primary::BG_HOVER`,
//!   `platform/density/size/default/lvl5/height` is
//!   `keys::platform::density::size::default::lvl5::HEIGHT`. `key.get()` in a binding reads the
//!   token where it is used and follows every change of it (`.bg(move ||
//!   BG.get().unwrap_or_default())`). Colors are adaptive: Light and Dark follow the appearance.
//!   [`ComponentSize::keys`], [`SizeKeys::level`], [`RoleKeys`] and [`TextStyleKeys`] pick keys
//!   by a component's size, level and role.
//! - **Modes.** The accent (cyan, sky, blue), the density (desktop, touch) and the OS (windows,
//!   macos, gnome, kde) are the document's modifiers, [`modifiers`]: `Accent::Sky.set()`,
//!   `set_modifier("density", "touch")`, TSX `setModifier`, and for a part of the app
//!   `theme_scope().modifiers(..)` / `<ThemeScope modifiers>`. Each starts at the document's
//!   default (cyan, desktop, windows): RayX sets none itself, the app picks them. Light and Dark is
//!   the appearance, in every context (`set_color_scheme`, the app's `nsh.json` `"appearance"`).
//! - **Custom themes** are NSH's: `update_tokens(Tokens::default().with(KEY, color!("#7c3aed",
//!   "#a78bfa")))` and `reset_tokens([KEY.name()])`, the app's `nsh.json` theme file (tokens by
//!   name: `"roles-primary-bg": "#7c3aed"`), and `ThemeScope`.
//! - **Names.** In theme files, TSX classes and `token()`, a token is named by its path after its
//!   collection (`theme.colors`, `theme.effects`, `platform.density`, `platform.os`) in kebab
//!   case, behind its kind's namespace: `roles-primary-bg` (`bg-roles-primary-bg`),
//!   `surfaces-text` (`text-surfaces-text`), `spacing-size-default-lvl5-height`
//!   (`h-size-default-lvl5-height`), `radius-size-default-borders-radius`
//!   (`rounded-size-default-borders-radius`). A group named as its tokens' namespace adds no
//!   prefix: `spacing-gap1` (`gap-gap1`), `shadow-default` (`shadow-default`). A token named as
//!   one of Tailwind's sizes keeps Tailwind's class, so it is named through `var()`: `shadow-md`
//!   is `shadow-(--shadow-md)`, `blur-md` is `blur-(--blur-md)`.
//! - **Roles.** The document maps nsh-base's roles onto RayX's tokens (`"roles"`), so what NSH
//!   draws itself (alerts, menus, scroll bars, text views, the default font) takes RayX's colors,
//!   radius and fonts.

use nsh_core::element::{AdaptiveColor, TokenKey, TokenValue};
use nsh_core::geometry::Points;
use nsh_core::prelude::*;

/// One typed key per token of RayX's document, in modules by the token's path, and the modifier
/// enums ([`modifiers`](self::modifiers)).
pub mod keys {
    nsh_core::element::theme_keys!("theme.json");
}

/// The document's modifiers: [`Accent`](modifiers::Accent), [`Density`](modifiers::Density) and
/// [`Os`](modifiers::Os), each an enum of its contexts (`NAME`, `ALL`, `DEFAULT`, `name()`,
/// `set()`, `current()`).
pub use keys::modifiers;

/// RayX's theme document, as [`crate::register`] registers it.
pub const DOCUMENT: &str = include_str!("../../theme.json");

/// The value of `key` where it is read (reactive in a binding), or the kind's default when the
/// document has no such token.
pub fn value<V: TokenValue + Default>(key: TokenKey<V>) -> V {
    key.get().unwrap_or_default()
}

/// A component's size (Figma's `size` property): every component height comes from a level in
/// one of these.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, PropEnum)]
pub enum ComponentSize {
    /// Dense toolbars, tables and inspectors.
    Small,
    /// Most forms and dialogs.
    #[default]
    Default,
    /// Touch layouts and prominent calls to action.
    Large,
}

impl ComponentSize {
    /// Every size, smallest first.
    pub const ALL: [ComponentSize; 3] = [
        ComponentSize::Small,
        ComponentSize::Default,
        ComponentSize::Large,
    ];

    /// Its name in Figma and TSX.
    pub const fn name(self) -> &'static str {
        match self {
            ComponentSize::Small => "small",
            ComponentSize::Default => "default",
            ComponentSize::Large => "large",
        }
    }

    /// The keys of this size (`platform.density.size.<size>`).
    pub const fn keys(self) -> &'static SizeKeys {
        match self {
            ComponentSize::Small => &SMALL,
            ComponentSize::Default => &DEFAULT,
            ComponentSize::Large => &LARGE,
        }
    }
}

/// The keys of one level of a size (`platform.density.size.<size>.lvl<n>`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelKeys {
    /// The outer height of the components on the level.
    pub height: TokenKey<Points>,
    /// The height of the nested element (a switch thumb, a segment, an icon in a row).
    pub inner_height: TokenKey<Points>,
    /// The space between the outer edge and the nested element, on every side.
    pub inner_inset: TokenKey<Points>,
    /// The space between the left or right edge and the content.
    pub inset: TokenKey<Points>,
    /// The size of an adornment: an icon, or a slot holding a badge or a small control.
    pub adornment_size: TokenKey<Points>,
}

/// The keys of a text style: font size, line height and letter spacing in points, and the weight
/// (CSS's 100 to 900).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TextStyleKeys {
    pub font_size: TokenKey<Points>,
    pub line_height: TokenKey<Points>,
    pub font_weight: TokenKey<f32>,
    pub letter_spacing: TokenKey<Points>,
}

/// The text styles of a size (`platform.density.size.<size>.text`, Figma's `text/size/<size>/*`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SizeTextKeys {
    pub regular: TextStyleKeys,
    pub code: TextStyleKeys,
    pub subtitle1_bold: TextStyleKeys,
    pub subtitle1_regular: TextStyleKeys,
    pub title1_bold: TextStyleKeys,
    pub title1_regular: TextStyleKeys,
    pub title2_regular: TextStyleKeys,
    pub title3_regular: TextStyleKeys,
}

/// The keys of one component size (`platform.density.size.<size>`): levels 1 to 7, corner radii,
/// spacing and text styles.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SizeKeys {
    /// Levels 1 to 7 ([`Self::level`]).
    pub levels: [LevelKeys; 7],
    /// The outer corner radius of the size's components.
    pub radius: TokenKey<Points>,
    /// The corner radius of elements nested in a component, and of the smallest components.
    pub radius_inner: TokenKey<Points>,
    /// The space between the parts of one element: icon, label, caret, badge.
    pub content: TokenKey<Points>,
    /// The space between the elements of a bar or group.
    pub items: TokenKey<Points>,
    /// The size's text styles.
    pub text: SizeTextKeys,
}

impl SizeKeys {
    /// Level `n` (1 to 7; others clamp to that range).
    pub const fn level(&self, n: u8) -> LevelKeys {
        let index = match n {
            0 | 1 => 0,
            2..=7 => n as usize - 1,
            _ => 6,
        };
        self.levels[index]
    }
}

/// The keys of a text style at `$path`, a module of [`keys`] with `FONT_SIZE`, `LINE_HEIGHT`,
/// `FONT_WEIGHT` and `LETTER_SPACING`: `text_style_keys!(keys::platform::density::typography::h3)`.
#[macro_export]
macro_rules! text_style_keys {
    ($($path:ident)::+) => {
        $crate::theme::TextStyleKeys {
            font_size: $($path)::+::FONT_SIZE,
            line_height: $($path)::+::LINE_HEIGHT,
            font_weight: $($path)::+::FONT_WEIGHT,
            letter_spacing: $($path)::+::LETTER_SPACING,
        }
    };
}

macro_rules! level_keys {
    ($size:ident, $lvl:ident) => {
        LevelKeys {
            height: keys::platform::density::size::$size::$lvl::HEIGHT,
            inner_height: keys::platform::density::size::$size::$lvl::INNER_HEIGHT,
            inner_inset: keys::platform::density::size::$size::$lvl::INNER_INSET,
            inset: keys::platform::density::size::$size::$lvl::INSET,
            adornment_size: keys::platform::density::size::$size::$lvl::ADORNMENT_SIZE,
        }
    };
}

macro_rules! size_keys {
    ($size:ident) => {
        SizeKeys {
            levels: [
                level_keys!($size, lvl1),
                level_keys!($size, lvl2),
                level_keys!($size, lvl3),
                level_keys!($size, lvl4),
                level_keys!($size, lvl5),
                level_keys!($size, lvl6),
                level_keys!($size, lvl7),
            ],
            radius: keys::platform::density::size::$size::borders::RADIUS,
            radius_inner: keys::platform::density::size::$size::borders::RADIUS_INNER,
            content: keys::platform::density::size::$size::spacing::CONTENT,
            items: keys::platform::density::size::$size::spacing::ITEMS,
            text: SizeTextKeys {
                regular: text_style_keys!(keys::platform::density::size::$size::text::regular),
                code: text_style_keys!(keys::platform::density::size::$size::text::code),
                subtitle1_bold: text_style_keys!(
                    keys::platform::density::size::$size::text::subtitle1_bold
                ),
                subtitle1_regular: text_style_keys!(
                    keys::platform::density::size::$size::text::subtitle1_regular
                ),
                title1_bold: text_style_keys!(
                    keys::platform::density::size::$size::text::title1_bold
                ),
                title1_regular: text_style_keys!(
                    keys::platform::density::size::$size::text::title1_regular
                ),
                title2_regular: text_style_keys!(
                    keys::platform::density::size::$size::text::title2_regular
                ),
                title3_regular: text_style_keys!(
                    keys::platform::density::size::$size::text::title3_regular
                ),
            },
        }
    };
}

static SMALL: SizeKeys = size_keys!(small);
static DEFAULT: SizeKeys = size_keys!(default);
static LARGE: SizeKeys = size_keys!(large);

/// The color keys of one role (`theme.colors.roles.<role>`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RoleKeys {
    pub accent: TokenKey<AdaptiveColor>,
    pub bg: TokenKey<AdaptiveColor>,
    pub bg_active: TokenKey<AdaptiveColor>,
    pub bg_hover: TokenKey<AdaptiveColor>,
    pub bg_selected: TokenKey<AdaptiveColor>,
    pub bg_selected_hover: TokenKey<AdaptiveColor>,
    pub bg_translucent: TokenKey<AdaptiveColor>,
    pub text: TokenKey<AdaptiveColor>,
    pub text_muted: TokenKey<AdaptiveColor>,
    pub text_subtle: TokenKey<AdaptiveColor>,
}

macro_rules! role_keys {
    ($role:ident) => {
        RoleKeys {
            accent: keys::theme::colors::roles::$role::ACCENT,
            bg: keys::theme::colors::roles::$role::BG,
            bg_active: keys::theme::colors::roles::$role::BG_ACTIVE,
            bg_hover: keys::theme::colors::roles::$role::BG_HOVER,
            bg_selected: keys::theme::colors::roles::$role::BG_SELECTED,
            bg_selected_hover: keys::theme::colors::roles::$role::BG_SELECTED_HOVER,
            bg_translucent: keys::theme::colors::roles::$role::BG_TRANSLUCENT,
            text: keys::theme::colors::roles::$role::TEXT,
            text_muted: keys::theme::colors::roles::$role::TEXT_MUTED,
            text_subtle: keys::theme::colors::roles::$role::TEXT_SUBTLE,
        }
    };
}

impl RoleKeys {
    /// The neutral role (`theme.colors.roles.neutral`; its `bgStrong` is
    /// `keys::theme::colors::roles::neutral::BG_STRONG`).
    pub const NEUTRAL: RoleKeys = role_keys!(neutral);
    /// The primary role, the accent's hue.
    pub const PRIMARY: RoleKeys = role_keys!(primary);
    /// The danger role.
    pub const DANGER: RoleKeys = role_keys!(danger);
    /// The success role.
    pub const SUCCESS: RoleKeys = role_keys!(success);
}

/// Gives `element` the text style `style`, bound: its font size, line height and letter spacing
/// follow the tokens (a modifier, a custom theme) as they change. The weight is read once, when
/// the view is made: NSH's weights are no bindings.
///
/// ```no_run
/// use nsh_core::prelude::*;
/// use rayx_components::text_style_keys;
/// use rayx_components::theme::{bind_text_style, keys, value};
///
/// let _ = bind_text_style(
///     text("Settings"),
///     text_style_keys!(keys::platform::density::typography::h3),
/// )
/// .text_color(move || value(keys::theme::colors::surfaces::TEXT));
/// ```
///
/// # Panics
///
/// Outside the reactive runtime: call it where views are made.
pub fn bind_text_style<E: Styled>(element: E, style: TextStyleKeys) -> E {
    element
        .text_size(move || px(value(style.font_size).0))
        .line_height(move || px(value(style.line_height).0))
        .letter_spacing(move || px(value(style.letter_spacing).0))
        .font_weight(weight(untracked(|| value(style.font_weight))))
}

/// A token's font weight (CSS's 100 to 900) as NSH's.
pub fn weight(value: f32) -> FontWeight {
    FontWeight(value.round().clamp(1.0, 1000.0) as u16)
}
